// Verified against live Zendesk and the OpenAI API. Last verified 2026-09-03.
//
// Category field: every instance has exactly ONE spam option (name "Spam",
// value "spam") and ONE duplicate option ("Duplicate contact",
// value "duplicate_contact"). Identical across all 16 reachable instances.
// There is no "Spam & Marketing" option anywhere.
//
// Wrong brand: the "Different platform/website" option exists on only 10 of 16
// instances, always with value "different_platform/website". It is MISSING on
// mindspree, mobitrace, myimage, realchecker, scannerly and vinready - the six
// instances using the shorter "Category" taxonomy. Left blank there on purpose;
// writing a non-existent option value would be rejected by Zendesk.
//
// Wrong brand macro: "Different Provider - Automation" (created 2026-09-02)
// exists ONLY on personality. A macro search across the other 15 instances
// returned zero hits, so CS has to create it per brand before this can be
// enabled anywhere else.
//
// Language field: NOT uniform.
//   en      -> brainiqtest, lovestyle, pdfhelp, personality, resumewise, unicopy
//   english -> mindspree, myimage, realchecker
// Required: true on 7 of the 9 brands running the CS automation.
//
// lovestyle_dev could not be read - the Development test Zendesk credential
// returns 401. Values assumed by convention.
//
// Model: gpt-5.4-nano, chosen over gpt-4.1-nano which the API reports as
// shutting down 2026-10-23.

const ENGLISH_BY_PROJECT = {
  brainiqtest_prod: 'en',
  lovestyle_dev: 'en',
  lovestyle_prod: 'en',
  mindspree_prod: 'english',
  myimage_prod: 'english',
  pdfhelp_prod: 'en',
  personality_prod: 'en',
  realchecker_prod: 'english',
  resumewise_prod: 'en',
  unicopy_prod: 'en'
};

// Only the instances that actually have the option.
const WRONG_BRAND_CATEGORY_PROJECTS = [
  'brainiqtest_prod',
  'chatbotonline_prod',
  'lovelanguagesupport_prod',
  'lovestyle_prod',
  'myqrcode_prod',
  'pdfhelp_prod',
  'personality_prod',
  'qrcreate_prod',
  'resumewise_prod',
  'unicopy_prod'
];

// Only personality has the macro so far.
const WRONG_BRAND_MACRO_BY_PROJECT = {
  personality_prod: 38846759877149
};

const PROJECTS = [
  'brainiqtest_prod',
  'chatbotonline_prod',
  'lovelanguagesupport_prod',
  'lovestyle_dev',
  'lovestyle_prod',
  'mindspree_prod',
  'mobitrace_prod',
  'myimage_prod',
  'myqrcode_prod',
  'pdfhelp_prod',
  'personality_prod',
  'qrcreate_prod',
  'realchecker_prod',
  'resumewise_prod',
  'scannerly_prod',
  'unicopy_prod',
  'vinready_prod'
];

return PROJECTS.map(p => ({
  json: {
    project_key: p,
    category_value_spam_marketing: 'spam',
    category_value_duplicate_contact: 'duplicate_contact',
    category_value_wrong_brand: WRONG_BRAND_CATEGORY_PROJECTS.indexOf(p) > -1 ? 'different_platform/website' : '',
    macro_wrong_brand_id: WRONG_BRAND_MACRO_BY_PROJECT[p] || 0,
    language_value_english: ENGLISH_BY_PROJECT[p] || '',
    spam_confidence_threshold: 0.97,
    spam_model_id: 'gpt-5.4-nano'
  }
}));
